package com.marketplace.order;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.cache.annotation.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.mongodb.repository.MongoRepository; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.net.URI; import java.time.Instant; import java.util.*;
interface OrderRepository extends JpaRepository<Order,Long>{} interface OrderHistoryRepository extends MongoRepository<OrderHistory,String>{ List<OrderHistory> findByOrderIdOrderByOccurredAtDesc(Long id); } @RestController @RequestMapping("/api/orders") class OrderController { private final OrderRepository orders;private final OrderHistoryRepository history; OrderController(OrderRepository o,OrderHistoryRepository h){orders=o;history=h;} record Request(@NotNull @Positive Long customerId,@NotNull @Positive BigDecimal total){} @PostMapping @Transactional ResponseEntity<Order> create(@Valid @RequestBody Request r){var order=orders.save(new Order(r.customerId(),r.total()));history.save(new OrderHistory(null,order.id,"ORDER_CREATED",Instant.now()));return ResponseEntity.created(URI.create("/api/orders/"+order.id)).body(order);}@GetMapping("/{id}") @Cacheable(value="order",key="#id") Order get(@PathVariable Long id){return orders.findById(id).orElseThrow();}@GetMapping("/{id}/history") List<OrderHistory> history(@PathVariable Long id){return history.findByOrderIdOrderByOccurredAtDesc(id);} }
